{"command": "cd /workspace && python3 << 'EOF'
import csv, json

awards = list(csv.DictReader(open('batch/awards.csv')))
hits = [json.loads(l) for l in open('batch/media_hits.jsonl')]

# PIs and co-PIs
names = {}
for a in awards:
    names.setdefault(a['pi_name'], []).append((a['award_id'], 'PI', a['institution']))
    if a['co_pi']:
        names.setdefault(a['co_pi'], []).append((a['award_id'], 'co-PI', a['institution']))

hit_names = {h['pi_name'] for h in hits}
print("=== PI/co-PI name matches against media feed ===")
for n in sorted(names):
    if n in hit_names:
        for rec in names[n]:
            print(f"  FEED MATCH: {n} -> {rec}")
# near-miss collisions
print("\n=== Feed names not matching any PI/co-PI exactly ===")
for hn in sorted(hit_names):
    if hn not in names:
        print("  ", hn)

# Neutral vs critical hits
print("\n=== Hit classification ===")
for h in hits:
    print(f"{h['hit_id']} {h['pi_name']:<25} {h['tone']}")
EOF"}
